import React from 'react';
import './CaseOpeningSplashUnified.css';

function themeFor(name='') {
  const n=String(name).toLowerCase();
  if(n.includes('rifle arsenal') || n.includes('assault rifle')) return {label:'RIFLE ARSENAL', sub:'FUSILS D’ASSAUT', accent:'#9f354d', accent2:'#ef6b84', symbol:'AK', deco:'rifle'};
  if(n.includes('sniper arsenal') || n.includes('sniper')) return {label:'SNIPER ARSENAL', sub:'SNIPERS & AWP', accent:'#2d6f9a', accent2:'#6fc2ff', symbol:'AWP', deco:'sniper'};
  if(n.includes('pistol arsenal') || n.includes('pistol')) return {label:'PISTOL ARSENAL', sub:'PISTOLETS', accent:'#a36d25', accent2:'#f1c15d', symbol:'DE', deco:'pistol'};
  if(n.includes('knife arsenal') || n.includes('knives arsenal')) return {label:'KNIFE ARSENAL', sub:'COUTEAUX', accent:'#a87b2b', accent2:'#f3c971', symbol:'✦', deco:'knife'};
  if(n.includes('gloves arsenal') || n.includes('glove arsenal')) return {label:'GLOVES ARSENAL', sub:'GANTS', accent:'#356d92', accent2:'#7ac5ef', symbol:'✋', deco:'gloves'};
  if(n.includes('beginner')) return {label:'BEGINNER CASE',sub:'DROP DE DÉPART',accent:'#2878b5',accent2:'#66b5ee',symbol:'W',deco:'beginner'};
  if(n.includes('advanced')) return {label:'ADVANCED CASE',sub:'DROP AVANCÉ',accent:'#7047ad',accent2:'#b18cff',symbol:'W',deco:'advanced'};
  if(n.includes('elite')) return {label:'ELITE CASE',sub:'DROP PREMIUM',accent:'#c23f56',accent2:'#ff8396',symbol:'W',deco:'elite'};
  if(n.includes('ak specialist')) return {label:'AK SPECIALIST',sub:'AK-47',accent:'#9b5c28',accent2:'#f0ad5a',symbol:'AK',deco:'ak'};
  if(n.includes('awp specialist')) return {label:'AWP SPECIALIST',sub:'AWP',accent:'#8d6b2b',accent2:'#f0cb67',symbol:'AWP',deco:'awp'};
  return {label:String(name||'WELLCASE').toUpperCase(),sub:'DROP SÉCURISÉ',accent:'#4d5c73',accent2:'#94aac4',symbol:'W',deco:'generic'};
}

export default function CaseOpeningSplashUnified({caseData}) {
  const t=themeFor(caseData?.name);
  return <div className="wc47-splash" data-splash-version="47" style={{'--s-accent':t.accent,'--s-accent2':t.accent2}}>
    <div className="wc47-stars"/><div className="wc47-orb"/>
    <div className={`wc47-shell ${t.deco}`}>
      <div className="wc47-brand">WELLCASE <span>SECURE DROP</span></div>
      <div className="wc47-kicker">OUVERTURE DE LA CAISSE</div>
      <h1>{t.label}</h1><p>{t.sub}</p>
      <div className="wc47-stage">
        <div className="wc47-deco deco-left"/><div className="wc47-deco deco-right"/>
        <div className="wc47-crate"><div className="wc47-lid"/><div className="wc47-body"><div className="wc47-bolt a"/><div className="wc47-bolt b"/><div className="wc47-bolt c"/><div className="wc47-bolt d"/><div className="wc47-logo">{t.symbol}</div><div className="wc47-name">WELLCASE</div><div className="wc47-case-name">{t.label}</div></div></div>
      </div>
      <div className="wc47-status"><span/> DROP SÉCURISÉ — RÉSULTAT DÉJÀ DÉTERMINÉ</div>
      <div className="wc47-progress"><i/></div>
    </div>
  </div>
}
